PAGE = dict(
    slug='isoshell',
    title='Pane::isoshell',
    signature='Trace& Pane::isoshell(Series values, int level_count = 4)\nTrace& Pane::isoshell(Series x, Series y, Series z, Series values, int level_count = 4)\nTrace& Pane::isoshell(Series x, Series y, Series z, Series values, std::vector<double> levels)',
    intro='Adds **isosurfaces**: for a field with a value at every point of a three-dimensional grid, the surfaces on which the field takes given values, drawn as nested shells. It is [`contour`](contour.md) one dimension up, and shows the shape of a volume of data, such as a density, a temperature or an electric potential.\n\n`values` is a rank-3 field, indexed along x, y and z.\n\n| Call | Coordinates | Levels |\n|---|---|---|\n| `isoshell(values, level_count = 4)` | The indices 1, 2, 3, ... | `level_count` evenly spaced. |\n| `isoshell(x, y, z, values, level_count = 4)` | Given: one series for each axis, with the extent of `values` along it. | `level_count` evenly spaced. |\n| `isoshell(x, y, z, values, levels)` | Given. | Exactly the container `levels`. |\n\nThe levels are spread between the lowest and highest value of the field, and the count must be positive. A shell is coloured by its level. Inner shells are hidden by outer ones unless the trace is [transparent](../trace/transparent.md).',
    parameters='**values** (`Series`-convertible, rank 3)\n    The field.\n\n**x**, **y**, **z** (`Series`-convertible, optional)\n    The coordinates along each axis.\n\n**level_count** (`int`, default 4) or **levels** (container)\n    How many shells, or at which values.',
    returns='`Trace&`\n    The new trace.',
    examples=[
        dict(id='default', text='A field with a value at each point of a 12 by 12 by 12 grid, here the squared distance from the centre. By default four levels are chosen, and a nested shell is drawn for each: shells of equal distance around the centre.',
             code='auto fig = studio("isoshell_default");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(field);\nfig.save_svg("figure.svg");'),
        dict(id='count', text='A count of levels: two shells show the inside of the nest.',
             code='auto fig = studio("isoshell_count");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(field, 2);\nfig.save_svg("figure.svg");'),
        dict(id='coordinates', text='With coordinates of your own the field is placed in space: the axes run from -1 to 1 here, so the shells are placed around the origin and the axes are labelled in those units.',
             code='auto fig = studio("isoshell_coordinates");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(axis, axis, axis, field);\nfig.save_svg("figure.svg");'),
        dict(id='coordinates_count', text='Coordinates and a count of levels.',
             code='auto fig = studio("isoshell_coordinates_count");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(axis, axis, axis, field, 3);\nfig.save_svg("figure.svg");'),
        dict(id='levels', text='Explicit levels, in a container: the shells at the squared distances 0.2 and 0.8.',
             code='auto fig = studio("isoshell_levels");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(axis, axis, axis, field, std::vector<double>{0.2, 0.8});\nfig.save_svg("figure.svg");'),
        dict(id='transparent', text='The shells hide one another. A transparent trace shows the inner ones through the outer.',
             code='auto fig = studio("isoshell_transparent");\nauto& pane = fig.pane3("p");\nconst std::int64_t n = 12;\nstd::vector<double> axis(static_cast<std::size_t>(n)), values(static_cast<std::size_t>(n * n * n));\nfor (std::int64_t i = 0; i < n; ++i) axis[static_cast<std::size_t>(i)] = -1.0 + 2.0 * i / (n - 1);\nfor (std::int64_t i = 0; i < n; ++i) {\n  for (std::int64_t j = 0; j < n; ++j) {\n    for (std::int64_t k = 0; k < n; ++k) {\n      const double x = axis[static_cast<std::size_t>(i)], y = axis[static_cast<std::size_t>(j)], z = axis[static_cast<std::size_t>(k)];\n      values[static_cast<std::size_t>((i * n + j) * n + k)] = x * x + y * y + z * z;\n    }\n  }\n}\nauto field = pluss::make_series(values, {n, n, n});\npane.isoshell(field, 3).transparent(true);\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("isoshell_errors");\n  auto& pane = fig.pane3("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("values are not a field", [](Pane& pane) { pane.isoshell(pluss::series::linspace(0.0, 1.0, 9, pluss::ScalarType::Float64).reshape({3, 3})); });\nreport("no levels", [](Pane& pane) { pane.isoshell(pluss::series::linspace(0.0, 1.0, 27, pluss::ScalarType::Float64).reshape({3, 3, 3}), 0); });\nauto fig = studio("isoshell_errors_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`isoshell` needs a volumetric pane. On a planar pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("isoshell_wrong_pane");\nauto& pane = fig.pane2("p");\ntry {\n  pane.isoshell(pluss::series::linspace(0.0, 1.0, 8, pluss::ScalarType::Float64).reshape({2, 2, 2}));\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::contour`](contour.md): contour lines of a two-dimensional field.', '[`Pane::sheet`](sheet.md): a surface over a grid.', '[`Trace::transparent`](../trace/transparent.md): see through the shells.'],
)
